firestore.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // Admin-only collection (optional)
    match /admin/{document} {
      allow read, write: if request.auth != null && request.auth.token.admin == true;
    }

    // Media metadata stored here (actual files are on Cloudinary).
    match /media/{document} {
      allow read: if true;
      allow write: if request.auth != null && request.auth.token.admin == true;
    }

    // Presentations: public read, admin write
    match /presentations/{document} {
      allow read: if true;
      allow write: if request.auth != null && request.auth.token.admin == true;
    }

    // Monitor assignment docs: monitor can read its own doc; only admins can write assignments
    match /monitors/{uid} {
      allow read: if request.auth != null && (request.auth.uid == uid || request.auth.token.admin == true);
      allow write: if request.auth != null && request.auth.token.admin == true;
    }

    match /{document=**} {
      allow read: if false;
      allow write: if false;
    }
  }
}
